mapper.select:
SELECT t2.short_name AS customer_name, t3.`name` AS bill_method_name, t1.id, t1.bill_no, t1.bill_date, t1.bill_user_id, t1.customer_id, t1.discount_amount, t1.actual_amount, t1.bill_method_id, t1.note, t1.create_time, t1.update_time, t1.creator, t1.updater FROM zc_bills t1 LEFT JOIN zc_customer t2 ON t1.customer_id = t2.id AND t2.deleted = 0 LEFT JOIN zc_bill_methods t3 ON t1.bill_method_id = t3.id AND t3.deleted = 0 WHERE t1.deleted = 0
AND t1.bill_no LIKE CONCAT('%', #{reqVO.billNo}, '%')
AND t1.bill_date BETWEEN #{reqVO.billDate[0]} AND #{reqVO.billDate[1]}
AND t1.bill_user_id = #{reqVO.billUserId}
AND t1.customer_id = #{reqVO.customerId}
AND t1.bill_method_id = #{reqVO.billMethodId}
ORDER BY t1.id DESC
